 "tool_failures": [
  {
   "tool": "create_promise",
   "rule": "Say the promise is recorded only after ok: true. If it fails, try once more. If it fails again, say you could not record it. Brief A: close as no_promise / service_error. Brief B: keep the promises that were recorded and call add_note with reason service_error for the failed product.",
   "source": "Brief A rule 37; Brief B rule 11"
  },
  {
   "tool": "verify_identity",
   "rule": "An unreadable date_of_birth value is rejected with ok=false and is not counted as a wrong answer. hint day_month_swapped: ask the customer to say the month as a word; that retry does not count as a wrong answer.",
   "source": "tool API verify_identity.answer description; Brief A rules 11 and 13"
  },
  {
   "tool": "get_account",
   "rule": "Refused until both questions are passed.",
   "source": "tool API get_account summary"
  },
  {
   "tool": "all tools (verify_identity, get_account, create_promise, add_note, schedule_callback, transfer_to_agent, close_call)",
   "rule": "`ok` is false when the action was not carried out. On a 500 the service failed, nothing was recorded, and the call may be repeated.",
   "source": "tool API, response descriptions for 200 and 500"
  },
  {
   "tool": "create_promise",
   "rule": "The service does not enforce the brief: it records a promise on a holiday or past the deadline without complaint. Following the brief is the agent's job.",
   "source": "tool API info.description"
  }
 ],
 "replaced_rules": [
  {
   "old": "Brief A: the customer is late on one product.",
   "new": "get_account returns one to three products, each with its own past_due, days_late and floor.",
   "source": "Brief B rule 1"
